#include "engine.hpp"
#include <cstdio>
#include <set>
void applyPatch(Engine&e,const nlohmann::json&patch){for(int i=0;i<PARAM_COUNT;i++){auto key=specs[i].key;double value=specs[i].def;if(patch["params"].contains(key)){auto v=patch["params"][key];if(v.is_string()){std::string all=specs[i].choices,want=v;int index=0;size_t pos=0;value=-1;while(pos<=all.size()){auto end=all.find('|',pos);if(all.substr(pos,end-pos)==want){value=index;break;}if(end==std::string::npos)break;pos=end+1;index++;}if(value<0)throw std::runtime_error(key);}else value=v.get<double>();}e.parameters[i]=normalized(i,value);}e.prepare(48000);e.config.matrixCount=0;e.config.sequence=false;e.loadParams();}
int main(){std::ifstream f("ui/factory-bank.json");auto bank=nlohmann::json::parse(f);Engine e;e.samples=readLibrary("samples");if(e.samples.size()!=116){printf("Missing sample assets\n");return 1;}for(auto&s:e.samples)if(s.data.empty()){printf("Empty sample %s\n",s.name.c_str());return 2;}std::set<std::string>names;std::set<uint64_t>fingerprints;int count=0;double quietest=1e9,loudest=0;std::ofstream report("bank-audio-report.csv");report<<"Preset,RMS,Peak,Fingerprint\n";for(auto&patch:bank){applyPatch(e,patch);bool bass=patch["category"].get<std::string>().find("Bass")!=std::string::npos;int note=bass?36:60;e.noteOn(note,.85);double energy=0,peak=0;uint64_t hash=1469598103934665603ULL;for(int s=0;s<72000;s++){if(s==24000)e.noteOn(note+7,.8);if(s==48000){e.noteOff(note);e.noteOff(note+7);}float l,r;e.sample(l,r);if(!std::isfinite(l)||!std::isfinite(r)||std::abs(l)>1.001||std::abs(r)>1.001){printf("Invalid audio %d\n",count);return 3;}energy+=l*l+r*r;peak=std::max(peak,std::max(std::abs(double(l)),std::abs(double(r))));if(s%31==0){int32_t q=int32_t(l*1000000);hash^=uint32_t(q);hash*=1099511628211ULL;}}double rms=std::sqrt(energy/144000);if(rms<.0001){printf("Silent patch %d %s\n",count,patch["name"].get<std::string>().c_str());return 4;}if(!fingerprints.insert(hash).second){printf("Duplicate audio %d\n",count);return 5;}names.insert(patch["name"]);quietest=std::min(quietest,rms);loudest=std::max(loudest,rms);report<<'"'<<patch["name"].get<std::string>()<<"\","<<rms<<','<<peak<<','<<hash<<'\n';count++;}printf("Bank: %d distinct audio renders, unique names, finite stereo output, note/release playback; 116 sample assets. RMS range %.5f–%.5f.\n",count,quietest,loudest);return count==350&&names.size()==350?0:6;}
